"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[44281],{61618(e,a,i){i.r(a),i.d(a,{assets:()=>c,contentTitle:()=>t,default:()=>u,frontMatter:()=>r,metadata:()=>s,toc:()=>l});const s=JSON.parse('{"id":"cursos/arquitectura-software/modulos/calidad-arquitectonica/cuestionario","title":"cuestionario","description":"2. [Investigar] \xbfQu\xe9 es el \\"Quality Attribute Workshop\\" (QAW) del SEI y c\xf3mo se diferencia de ATAM en el ciclo de vida del proyecto?","source":"@site/docs/cursos/arquitectura-software/modulos/11-calidad-arquitectonica/cuestionario.md","sourceDirName":"cursos/arquitectura-software/modulos/11-calidad-arquitectonica","slug":"/cursos/arquitectura-software/modulos/calidad-arquitectonica/cuestionario","permalink":"/sasf-temarios/cursos/arquitectura-software/modulos/calidad-arquitectonica/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"private":true,"sidebar_class_name":"private","sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/arquitectura-software/modulos/calidad-arquitectonica/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/arquitectura-software/modulos/calidad-arquitectonica/ejercicio"}}');var o=i(74848),n=i(28453);const r={private:!0,sidebar_class_name:"private",sidebar_label:"Cuestionario"},t=void 0,c={},l=[{value:"2. [Investigar] \xbfQu\xe9 es el &quot;Quality Attribute Workshop&quot; (QAW) del SEI y c\xf3mo se diferencia de ATAM en el ciclo de vida del proyecto?",id:"2-investigar-qu\xe9-es-el-quality-attribute-workshop-qaw-del-sei-y-c\xf3mo-se-diferencia-de-atam-en-el-ciclo-de-vida-del-proyecto",level:3},{value:"3. [Investigar] \xbfQu\xe9 es el modelo &quot;Availability, Latency, Throughput, Freshness&quot; (ALTF) de Google y c\xf3mo extiende los 9s de disponibilidad que cubre la clase?",id:"3-investigar-qu\xe9-es-el-modelo-availability-latency-throughput-freshness-altf-de-google-y-c\xf3mo-extiende-los-9s-de-disponibilidad-que-cubre-la-clase",level:3},{value:"4. [Investigar] \xbfQu\xe9 es &quot;Chaos Engineering&quot; seg\xfan <em>Principles of Chaos Engineering</em> (Netflix) y c\xf3mo se relaciona con la verificaci\xf3n de atributos de calidad en producci\xf3n vs las t\xe1cticas de dise\xf1o?",id:"4-investigar-qu\xe9-es-chaos-engineering-seg\xfan-principles-of-chaos-engineering-netflix-y-c\xf3mo-se-relaciona-con-la-verificaci\xf3n-de-atributos-de-calidad-en-producci\xf3n-vs-las-t\xe1cticas-de-dise\xf1o",level:3},{value:"5. [Conectar] La clase presenta ATAM como m\xe9todo de evaluaci\xf3n. \xbfC\xf3mo se relaciona esto con el &quot;Utility Tree&quot; del SEI y c\xf3mo se construye un utility tree para E-Commerce Platform?",id:"5-conectar-la-clase-presenta-atam-como-m\xe9todo-de-evaluaci\xf3n-c\xf3mo-se-relaciona-esto-con-el-utility-tree-del-sei-y-c\xf3mo-se-construye-un-utility-tree-para-e-commerce-platform",level:3},{value:"6. [Conectar] La clase cubre performance con latencia p50/p95/p99. \xbfC\xf3mo se relaciona esto con la &quot;Long Tail&quot; de latencia que documenta Gil Tene y c\xf3mo impacta decisiones arquitect\xf3nicas?",id:"6-conectar-la-clase-cubre-performance-con-latencia-p50p95p99-c\xf3mo-se-relaciona-esto-con-la-long-tail-de-latencia-que-documenta-gil-tene-y-c\xf3mo-impacta-decisiones-arquitect\xf3nicas",level:3},{value:"7. [Conectar] La clase cubre seguridad con CIA Triad y estrategias. \xbfC\xf3mo se relaciona esto con el &quot;Zero Trust Architecture&quot; (NIST SP 800-207) y qu\xe9 implicancias arquitect\xf3nicas tiene?",id:"7-conectar-la-clase-cubre-seguridad-con-cia-triad-y-estrategias-c\xf3mo-se-relaciona-esto-con-el-zero-trust-architecture-nist-sp-800-207-y-qu\xe9-implicancias-arquitect\xf3nicas-tiene",level:3},{value:"8. [Cuestionar] \xbfSon los &quot;9&#39;s de disponibilidad&quot; una m\xe9trica \xfatil o un mito de marketing? La cr\xedtica de Charity Majors (Honeycomb) sobre SLOs significativos.",id:"8-cuestionar-son-los-9s-de-disponibilidad-una-m\xe9trica-\xfatil-o-un-mito-de-marketing-la-cr\xedtica-de-charity-majors-honeycomb-sobre-slos-significativos",level:3},{value:"9. [Cuestionar] \xbfEs ATAM demasiado pesado para equipos \xe1giles? \xbfPuede la evaluaci\xf3n de arquitectura ser continua en lugar de un evento puntual?",id:"9-cuestionar-es-atam-demasiado-pesado-para-equipos-\xe1giles-puede-la-evaluaci\xf3n-de-arquitectura-ser-continua-en-lugar-de-un-evento-puntual",level:3},{value:"10. [Cuestionar] \xbfEs la seguridad un atributo de calidad &quot;no funcional&quot; o es un atributo funcional? El debate sobre si la seguridad debe ser dise\xf1ada como requisito funcional desde el inicio.",id:"10-cuestionar-es-la-seguridad-un-atributo-de-calidad-no-funcional-o-es-un-atributo-funcional-el-debate-sobre-si-la-seguridad-debe-ser-dise\xf1ada-como-requisito-funcional-desde-el-inicio",level:3}];function d(e){const a={code:"code",em:"em",h3:"h3",hr:"hr",p:"p",strong:"strong",...(0,n.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(a.h3,{id:"2-investigar-qu\xe9-es-el-quality-attribute-workshop-qaw-del-sei-y-c\xf3mo-se-diferencia-de-atam-en-el-ciclo-de-vida-del-proyecto",children:'2. [Investigar] \xbfQu\xe9 es el "Quality Attribute Workshop" (QAW) del SEI y c\xf3mo se diferencia de ATAM en el ciclo de vida del proyecto?'}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),": El QAW, tambi\xe9n del SEI (Barbacci, Ellison, 2001), es un m\xe9todo para ",(0,o.jsx)(a.strong,{children:"elicitar"})," atributos de calidad y escenarios antes de dise\xf1ar la arquitectura, mientras que ATAM es para ",(0,o.jsx)(a.strong,{children:"evaluar"}),' una arquitectura ya dise\xf1ada. QAW se ejecuta en la fase de requisitos, con stakeholders de negocio y t\xe9cnicos, y produce un "utility tree" de escenarios de calidad priorizados que gu\xedan el dise\xf1o arquitect\xf3nico. ATAM se ejecuta despu\xe9s, eval\xfaa si la arquitectura propuesta satisface esos escenarios, e identifica riesgos. La clase present\xf3 escenarios de calidad y ATAM como si fueran parte del mismo proceso, pero en la pr\xe1ctica industrial, QAW es el input de ATAM: primero elicit\xe1s escenarios con negocio (QAW), luego dise\xf1\xe1s la arquitectura, luego evalu\xe1s (ATAM).']}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),": La metodolog\xeda completa del SEI distingue entre elicitaci\xf3n (QAW) y evaluaci\xf3n (ATAM). Para E-Commerce Platform: primero har\xedas un QAW con stakeholders para priorizar disponibilidad (99.9%) sobre performance, luego dise\xf1\xe1s la arquitectura hexagonal + microservicios, luego ATAM para evaluar si ese dise\xf1o cumple los escenarios. La clase no mencion\xf3 QAW, dejando un vac\xedo sobre c\xf3mo se llega a los escenarios de calidad."]}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"3-investigar-qu\xe9-es-el-modelo-availability-latency-throughput-freshness-altf-de-google-y-c\xf3mo-extiende-los-9s-de-disponibilidad-que-cubre-la-clase",children:'3. [Investigar] \xbfQu\xe9 es el modelo "Availability, Latency, Throughput, Freshness" (ALTF) de Google y c\xf3mo extiende los 9s de disponibilidad que cubre la clase?'}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),": Google, en su ",(0,o.jsx)(a.em,{children:"Site Reliability Engineering"})," book (2016), define 4 m\xe9tricas de calidad operacional: ",(0,o.jsx)(a.strong,{children:"Availability"})," (fracci\xf3n de tiempo que el sistema responde exitosamente, medido en 9s), ",(0,o.jsx)(a.strong,{children:"Latency"})," (tiempo para servir un request, medido en percentiles), ",(0,o.jsx)(a.strong,{children:"Throughput"})," (tasa de requests procesados), y ",(0,o.jsx)(a.strong,{children:"Freshness"})," (cu\xe1n actualizados est\xe1n los datos servidos). La clase cubre disponibilidad (9s) y performance (latencia), pero no ",(0,o.jsx)(a.strong,{children:"Freshness"}),' como m\xe9trica separada. Freshness es cr\xedtico en sistemas con consistencia eventual: un usuario puede recibir respuesta en 50ms (buena latencia), pero los datos pueden tener 5 minutos de antig\xfcedad (mala freshness). Google define SLOs para las 4 dimensiones y monitorea su cumplimiento con "error budgets."']}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),': El concepto de "freshness" es poco conocido fuera de Google pero esencial para sistemas CQRS y EDA. Si tu read model tiene 30 segundos de lag respecto al write model, tu disponibilidad y latencia pueden ser excelentes (el sistema "funciona"), pero la experiencia del usuario puede ser p\xe9sima (datos desactualizados). La clase no mencion\xf3 freshness como dimensi\xf3n de calidad.']}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsxs)(a.h3,{id:"4-investigar-qu\xe9-es-chaos-engineering-seg\xfan-principles-of-chaos-engineering-netflix-y-c\xf3mo-se-relaciona-con-la-verificaci\xf3n-de-atributos-de-calidad-en-producci\xf3n-vs-las-t\xe1cticas-de-dise\xf1o",children:['4. [Investigar] \xbfQu\xe9 es "Chaos Engineering" seg\xfan ',(0,o.jsx)(a.em,{children:"Principles of Chaos Engineering"})," (Netflix) y c\xf3mo se relaciona con la verificaci\xf3n de atributos de calidad en producci\xf3n vs las t\xe1cticas de dise\xf1o?"]}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),": Chaos Engineering, formalizado por Netflix (Casey Rosenthal, Nora Jones) en ",(0,o.jsx)(a.em,{children:"Principles of Chaos Engineering"})," (2017) y el libro ",(0,o.jsx)(a.em,{children:"Chaos Engineering"})," (2020), es la disciplina de experimentar en un sistema en producci\xf3n para generar confianza en su capacidad de resistir condiciones turbulentas. A diferencia de las t\xe1cticas arquitect\xf3nicas (que son ",(0,o.jsx)(a.strong,{children:"dise\xf1o"})," preventivo: circuit breaker, redundancia), Chaos Engineering es ",(0,o.jsx)(a.strong,{children:"verificaci\xf3n"})," emp\xedrica: inyect\xe1s fallos controlados (latencia, ca\xedda de servicio, partici\xf3n de red) y verific\xe1s que el sistema se comporte como esper\xe1s. La premisa: no sab\xe9s si tu arquitectura es resiliente hasta que la prob\xe1s en producci\xf3n. Netflix cre\xf3 Chaos Monkey, Chaos Kong, y FIT (Failure Injection Testing) para automatizar esta verificaci\xf3n."]}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"5-conectar-la-clase-presenta-atam-como-m\xe9todo-de-evaluaci\xf3n-c\xf3mo-se-relaciona-esto-con-el-utility-tree-del-sei-y-c\xf3mo-se-construye-un-utility-tree-para-e-commerce-platform",children:'5. [Conectar] La clase presenta ATAM como m\xe9todo de evaluaci\xf3n. \xbfC\xf3mo se relaciona esto con el "Utility Tree" del SEI y c\xf3mo se construye un utility tree para E-Commerce Platform?'}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),': El utility tree es el artefacto central de ATAM. Tiene una estructura jer\xe1rquica: ra\xedz = "Utility" (utilidad del sistema), nivel 1 = atributos de calidad (Performance, Availability, Security, etc.), nivel 2 = sub-atributos (bajo Performance: Latencia, Throughput), nivel 3 = escenarios de calidad concretos priorizados por importancia (H, M, L) y dificultad de implementaci\xf3n (H, M, L). Por ejemplo: Performance \u2192 Latencia \u2192 "Bajo carga de 500 usuarios concurrentes, la b\xfasqueda de productos responde en <200ms p95" (H, M). El utility tree prioriza escenarios para que ATAM se concentre en los de alta importancia y alta dificultad.']}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase mencion\xf3 ATAM y escenarios de calidad, pero no el utility tree que los conecta. Kazman y Clements en ",(0,o.jsx)(a.em,{children:"Evaluating Software Architectures"})," dedican un cap\xedtulo al utility tree como herramienta de priorizaci\xf3n. Sin utility tree, ten\xe9s una lista plana de escenarios; con utility tree, sab\xe9s exactamente cu\xe1les son los escenarios que hacen o rompen la arquitectura."]}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"6-conectar-la-clase-cubre-performance-con-latencia-p50p95p99-c\xf3mo-se-relaciona-esto-con-la-long-tail-de-latencia-que-documenta-gil-tene-y-c\xf3mo-impacta-decisiones-arquitect\xf3nicas",children:'6. [Conectar] La clase cubre performance con latencia p50/p95/p99. \xbfC\xf3mo se relaciona esto con la "Long Tail" de latencia que documenta Gil Tene y c\xf3mo impacta decisiones arquitect\xf3nicas?'}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),': Gil Tene (CTO de Azul Systems, creador de C4 garbage collector) populariz\xf3 el concepto de "long tail latency" en su charla ',(0,o.jsx)(a.em,{children:'"How NOT to Measure Latency"'}),' (2015). Su insight clave: el promedio de latencia es enga\xf1oso porque la distribuci\xf3n de latencia tiene una "cola larga" (algunos requests son much\xedsimo m\xe1s lentos que el promedio). Si 1 de cada 1000 requests tarda 10 segundos, el promedio puede ser 100ms (aceptable), pero para un usuario que experiment\xf3 los 10 segundos, el sistema "no funciona." Las decisiones arquitect\xf3nicas impactan la cola: un GC pause de 2 segundos en Java no afecta el p50 pero destruye el p99.9. Las t\xe1cticas: timeouts agresivos, hedged requests, y evitar puntos de serializaci\xf3n (locks, GC, single-threaded bottlenecks).']}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase present\xf3 percentiles, pero Tene explica por qu\xe9 el p99.9 es la m\xe9trica que importa para experiencia de usuario. Si ten\xe9s 10K usuarios concurrentes en E-Commerce Platform y 1 de cada 1000 experimenta 10 segundos de latencia, ten\xe9s 10 usuarios furiosos por segundo. Las decisiones arquitect\xf3nicas (s\xedncrono vs as\xedncrono, con pooling vs sin pooling, con ORM vs SQL directo) tienen impacto directo en la cola larga, no en el promedio."]}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"7-conectar-la-clase-cubre-seguridad-con-cia-triad-y-estrategias-c\xf3mo-se-relaciona-esto-con-el-zero-trust-architecture-nist-sp-800-207-y-qu\xe9-implicancias-arquitect\xf3nicas-tiene",children:'7. [Conectar] La clase cubre seguridad con CIA Triad y estrategias. \xbfC\xf3mo se relaciona esto con el "Zero Trust Architecture" (NIST SP 800-207) y qu\xe9 implicancias arquitect\xf3nicas tiene?'}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),": Zero Trust Architecture (ZTA), definido por NIST SP 800-207 (2020), es un modelo de seguridad donde no se conf\xeda en ning\xfan actor, dispositivo o red por defecto, incluso dentro del per\xedmetro corporativo. Las implicancias arquitect\xf3nicas son profundas: (1) ",(0,o.jsx)(a.strong,{children:"micro-segmentaci\xf3n"}),": cada servicio autentica cada request, incluso entre servicios internos (mTLS en service mesh), (2) ",(0,o.jsx)(a.strong,{children:"identity-based access"}),": tokens JWT con claims espec\xedficos, no API keys compartidas, (3) ",(0,o.jsx)(a.strong,{children:"continuous verification"}),": cada request se verifica contra pol\xedticas en tiempo real (no solo al iniciar sesi\xf3n), y (4) ",(0,o.jsx)(a.strong,{children:"least privilege"}),": cada servicio tiene acceso solo a los datos que necesita. La clase mencion\xf3 autenticaci\xf3n y autorizaci\xf3n, pero Zero Trust va m\xe1s all\xe1: asume que la red est\xe1 comprometida y dise\xf1a defensa en profundidad a nivel de aplicaci\xf3n."]}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),": NIST SP 800-207 es el est\xe1ndar de referencia para Zero Trust. Para E-Commerce Platform, Zero Trust significa que el Servicio de Pagos no conf\xeda en el Servicio de Pedidos solo porque est\xe1 en la misma VPC: cada request debe traer un token JWT con scope ",(0,o.jsx)(a.code,{children:"payment:create"})," y el Servicio de Pagos lo valida contra el identity provider."]}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"8-cuestionar-son-los-9s-de-disponibilidad-una-m\xe9trica-\xfatil-o-un-mito-de-marketing-la-cr\xedtica-de-charity-majors-honeycomb-sobre-slos-significativos",children:'8. [Cuestionar] \xbfSon los "9\'s de disponibilidad" una m\xe9trica \xfatil o un mito de marketing? La cr\xedtica de Charity Majors (Honeycomb) sobre SLOs significativos.'}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),': Charity Majors, CTO de Honeycomb, argumenta en su blog y charlas que los 9s son una m\xe9trica pobre porque miden "\xbfest\xe1 el sistema up?" pero no "\xbfest\xe1 el sistema \xfatil?" Un sistema puede estar "up" (servidor responde 200 OK) pero ser in\xfatil (respuestas vac\xedas, latencia de 30 segundos, datos incorrectos). Majors propone SLOs basados en ',(0,o.jsx)(a.strong,{children:"eventos de negocio"})," (\xbfel usuario pudo completar la compra?) en lugar de m\xe9tricas t\xe9cnicas (\xbfel load balancer recibi\xf3 respuesta?). Su cr\xedtica: obsesionarse con 99.99% lleva a arquitecturas conservadoras que evitan cualquier cambio con riesgo, sacrificando velocidad de desarrollo."]}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),': Majors es una voz influyente en observabilidad. La clase present\xf3 disponibilidad como m\xe9trica de 9s sin cuestionarla, pero la tendencia de la industria (Google SRE book, Honeycomb) es hacia SLOs orientados al negocio. Para E-Commerce: "99.9% de usuarios que intentan comprar, completan la compra en <10 segundos" es m\xe1s significativo que "el API Gateway responde 99.99% del tiempo."']}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"9-cuestionar-es-atam-demasiado-pesado-para-equipos-\xe1giles-puede-la-evaluaci\xf3n-de-arquitectura-ser-continua-en-lugar-de-un-evento-puntual",children:"9. [Cuestionar] \xbfEs ATAM demasiado pesado para equipos \xe1giles? \xbfPuede la evaluaci\xf3n de arquitectura ser continua en lugar de un evento puntual?"}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),": ATAM fue dise\xf1ado en los 90s para procesos waterfall o RUP, con talleres de 2-3 d\xedas. En entornos \xe1giles con sprints de 2 semanas, ATAM completo es inviable. La alternativa propuesta por Neal Ford en ",(0,o.jsx)(a.em,{children:"Building Evolutionary Architectures"}),": ",(0,o.jsx)(a.strong,{children:"fitness functions continuas"}),' que validan los atributos de calidad en cada build de CI/CD, reemplazando la evaluaci\xf3n puntual de ATAM con verificaci\xf3n continua automatizada. Sin embargo, Kazman y el SEI argumentan que ciertos an\xe1lisis de trade-offs (especialmente riesgos de seguridad) requieren juicio humano y no pueden ser automatizados. La postura intermedia: ATAM "light" (2-4 horas, solo para decisiones de alto impacto) + fitness functions para atributos automatizables.']}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),': Esta es la tensi\xf3n entre arquitectura tradicional (SEI) y arquitectura evolutiva (Ford). La clase present\xf3 ATAM sin discutir su aplicabilidad \xe1gil. La pr\xe1ctica emergente en ThoughtWorks: usar "Architecture Decision Records" como ATAM distribuido (cada ADR incluye un mini trade-off analysis) + fitness functions automatizadas.']}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"10-cuestionar-es-la-seguridad-un-atributo-de-calidad-no-funcional-o-es-un-atributo-funcional-el-debate-sobre-si-la-seguridad-debe-ser-dise\xf1ada-como-requisito-funcional-desde-el-inicio",children:'10. [Cuestionar] \xbfEs la seguridad un atributo de calidad "no funcional" o es un atributo funcional? El debate sobre si la seguridad debe ser dise\xf1ada como requisito funcional desde el inicio.'}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),': Tradicionalmente, la seguridad se clasifica como "non-functional requirement" (NFR) junto con performance y disponibilidad. La cr\xedtica moderna (Jim Manico, OWASP) es que tratar la seguridad como NFR la relega a una preocupaci\xf3n secundaria que se "agrega despu\xe9s." La seguridad deber\xeda ser tratada como requisito funcional: "el sistema DEBE autenticar usuarios con OAuth 2.0 + PKCE" y "el sistema DEBE encriptar datos PII en reposo con AES-256" son tan funcionales como "el sistema DEBE permitir crear pedidos." La ventaja de este framing: la seguridad entra en la definici\xf3n de done, en las historias de usuario, y en los criterios de aceptaci\xf3n, no en un documento separado de NFR que nadie lee.']}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),": OWASP y el BSIMM (Building Security In Maturity Model) promueven tratar seguridad como requisito de primera clase. La clase la clasific\xf3 como NFR siguiendo la taxonom\xeda tradicional del SEI, pero la tendencia en DevSecOps es integrar seguridad como parte del dise\xf1o desde el d\xeda 1, no como atributo no funcional a verificar despu\xe9s."]}),"\n",(0,o.jsx)(a.hr,{})]})}function u(e={}){const{wrapper:a}={...(0,n.R)(),...e.components};return a?(0,o.jsx)(a,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},28453(e,a,i){i.d(a,{R:()=>r,x:()=>t});var s=i(96540);const o={},n=s.createContext(o);function r(e){const a=s.useContext(n);return s.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function t(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),s.createElement(n.Provider,{value:a},e.children)}}}]);